@users_bp.route("/<int:user_id>", methods=["PUT"])
@require_auth
def update_user(user_id: int):
    """Update profile fields (email, shipping preferences). Owner or admin."""
    session = get_session()
    user = session.get(User, user_id)
    if user is None:
        return jsonify({"error": "not found"}), 404
    payload = request.get_json(silent=True) or {}
    if "email" in payload:
        user.email = payload["email"]
    session.commit()
    return jsonify(user.to_dict(include_email=True))

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)

    return wrapper

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

